 "content": "def transform(grid):
    """Color repeated 3x3 binary motifs containing each clue with its clue color."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    clues = [(r, c, v) for r in range(h) for c, v in enumerate(grid[r]) if v not in (0, 1)]
    for r, c, color in clues:
        # Use the clue's 3x3 neighborhood as a shape signature; canvas outside
        # the grid is treated as background. Clue itself occupies a 1-cell.
        mask = []
        for dr in (-1, 0, 1):
            line = []
            for dc in (-1, 0, 1):
                rr, cc = r + dr, c + dc
                line.append(int(0 <= rr < h and 0 <= cc < w and grid[rr][cc] != 0))
            mask.append(line)
        for ar in range(h - 2):
            for ac in range(w - 2):
                if all(int(grid[ar + dr][ac + dc] != 0) == mask[dr][dc]
                       for dr in range(3) for dc in range(3)):
                    for dr in range(3):
                        for dc in range(3):
                            if mask[dr][dc] and grid[ar + dr][ac + dc] == 1:
                                out[ar + dr][ac + dc] = color
    return out
