def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    labels = {}
    colors = {}
    comp_id = 0
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in labels:
                continue
            comp_id += 1
            q = deque([(r, c)])
            labels[(r, c)] = comp_id
            color = None
            while q:
                rr, cc = q.popleft()
                if grid[rr][cc] not in (0, 1):
                    color = grid[rr][cc]
                for nr, nc in ((rr-1,cc),(rr+1,cc),(rr,cc-1),(rr,cc+1)):
                    if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] != 0 and (nr,nc) not in labels:
                        labels[(nr,nc)] = comp_id
                        q.append((nr,nc))
            colors[comp_id] = color
    # Clue-bearing connected figures: recolor the center of every solid 3x3
    # patch contained in that same figure.
    for r in range(1, h-1):
        for c in range(1, w-1):
            cid = labels.get((r, c))
            if cid is None or colors[cid] is None:
                continue
            if all(labels.get((rr, cc)) == cid
                   for rr in range(r-1, r+2) for cc in range(c-1, c+2)):
                if grid[r][c] == 1:
                    out[r][c] = colors[cid]
    return out
